<template><Card class="s1-ui"><header class="ui-header"><div><h2>{{selected?selected.storeName:'商户档案'}}</h2><p v-if="selected">{{selected.legalName}} <StatusTag :value="selected.state"/></p><p v-if="selected" class="ui-meta">Store {{selected.id}} · 资料 v{{selected.version}} · 负责人 {{selected.ownerName||'未提供'}}</p></div><div class="ui-actions"><Button @click="back">返回商户列表</Button><Button @click="reload">重新读取</Button></div></header><PageStatus v-bind="$data" :target="pendingTarget" @recover="recover()" @retry="recover(true)" @abandon="abandon"/><Tabs v-if="selected" v-model="tab" :animated="false" @on-click="loadTab"><TabPane label="基本资料" name="overview"><ProfileFields :profile="selected" :range="false"/><DetailSection title="经营状态"><FieldRow label="准入状态" :value="status(selected.admissionState)"/><FieldRow label="关闭原因" :value="selected.closedReason" wide/></DetailSection></TabPane><TabPane label="经营范围与资质" name="qualifications"><DetailSection title="已批准经营范围" :grid="false"><CategoryNames :ids="selected.categoryIds||[]"/></DetailSection><QualificationTable :records="selected.qualifications&&selected.qualifications.versions||[]" :revocable="can('admission.review')" :disabled="blocked" @revoke="revoke"/><p v-if="drafts.length" class="ui-note">有 {{drafts.length}} 份资质变更尚未生效。<Button v-if="can('admission.review')" type="text" @click="link('/s1/applications',{q:selected.storeName})">进入申请审核</Button></p></TabPane><TabPane label="合作与经营资格" name="cooperation"><Eligibility :embedded-store="selected.id"/><div class="ui-actions"><Button v-if="can('agreement.read')" @click="link('/s1/agreements',{targetStore:selected.id})">查看合作协议</Button><Button v-if="can('rule.read')" @click="link('/s1/commission-rules',{targetStore:selected.id})">查看佣金规则</Button><Button v-if="can('channel.onboard')" @click="link('/s1/submerchants',{targetStore:selected.id})">查看渠道关系</Button></div></TabPane><TabPane label="人员信息" name="staff"><Alert show-icon>平台只读核查，不提供邀请、角色修改或负责人转让。</Alert><Table :columns="staffColumns" :data="staffRows" no-data-text="暂无人员记录"><template slot="owner" slot-scope="{row}">{{row.owner?'负责人':'工作人员'}}</template><template slot="roles" slot-scope="{row}">{{row.roleNames.join('、')||'未提供'}}</template><template slot="state" slot-scope="{row}"><StatusTag :value="row.state"/></template></Table><Page class="ui-pagination" :total="staffTotal" :current="staffPage" :page-size="20" @on-change="staffPage=$event;loadStaff()"/></TabPane><TabPane label="履约方式与点位" name="fulfillment"><div v-if="can('fulfillment.inspect')"><p class="ui-note">履约设置由商户维护，平台仅核查。</p><Button type="primary" @click="link('/s1/fulfillment',{targetStore:selected.id})">查看本商户四方式及点位</Button></div><Alert v-else type="warning">当前角色没有履约核查权限，未请求点位资料。</Alert></TabPane><TabPane label="变更与操作记录" name="history"><HistoryTable :records="historyRows" :columns="historyColumns"/><Page class="ui-pagination" :total="historyTotal" :current="historyPage" :page-size="20" @on-change="historyPage=$event;loadHistory()"/></TabPane></Tabs><footer v-if="selected" class="ui-footer-actions"><Button @click="back">返回列表</Button><Button v-if="can('store.supervise')" :type="selected.state==='CLOSED'?'primary':'error'" :disabled="blocked" @click="supervise">{{selected.state==='CLOSED'?'恢复店铺':'关闭店铺'}}</Button></footer></Card></template>
<script>import page from './page';import PageStatus from './components/PageStatus';import StatusTag from './components/StatusTag';import ProfileFields from './components/ProfileFields';import DetailSection from './components/DetailSection';import FieldRow from './components/FieldRow';import CategoryNames from './components/CategoryNames';import QualificationTable from './components/QualificationTable';import HistoryTable from './components/HistoryTable';import Eligibility from './Eligibility';export default {mixins:[page],components:{PageStatus,StatusTag,ProfileFields,DetailSection,FieldRow,CategoryNames,QualificationTable,HistoryTable,Eligibility},data:()=>({staffRows:[],staffTotal:0,staffPage:1,historyRows:[],historyTotal:0,historyPage:1,tabTicket:0,staffColumns:[{title:'姓名／显示名',key:'displayName',minWidth:160},{title:'身份',slot:'owner',width:110},{title:'授权模板',slot:'roles',minWidth:200},{title:'状态',slot:'state',width:120},{title:'授权版本',key:'version',width:100}],historyColumns:[{title:'时间（上海）',slot:'time',minWidth:180},{title:'操作',slot:'action',minWidth:160},{title:'人员',key:'operatorName',minWidth:150},{title:'原版本',key:'beforeVersion',width:90},{title:'新版本',key:'afterVersion',width:90},{title:'原因',key:'reason',minWidth:220}]}),computed:{drafts(){return this.selected&&this.selected.qualifications&&this.selected.qualifications.drafts||[];}},watch:{'$route.params.id'(){this.tab='overview';this.tabTicket++;this.staffRows=[];this.historyRows=[];this.reload();}},mounted(){this.reload();},beforeDestroy(){this.tabTicket++;},methods:{reload(){return this.latest(()=>this.ui('/stores/'+this.$route.params.id),v=>{this.selected=v;},()=>{this.selected=null;});},loadTab(name){if(name==='staff')this.loadStaff();if(name==='history')this.loadHistory();},async loadStaff(){const id=this.selected.id,ticket=++this.tabTicket;this.staffRows=[];try{const v=await this.ui('/stores/'+id+'/staff',{pageNumber:this.staffPage,pageSize:20});if(ticket===this.tabTicket&&this.selected&&id===this.selected.id){this.staffRows=v.records;this.staffTotal=v.total;}}catch(e){if(ticket===this.tabTicket)this.error=e.message;}},async loadHistory(){const id=this.selected.id,ticket=++this.tabTicket;this.historyRows=[];try{const v=await this.ui('/stores/'+id+'/history',{pageNumber:this.historyPage,pageSize:20});if(ticket===this.tabTicket&&this.selected&&id===this.selected.id){this.historyRows=v.records;this.historyTotal=v.total;}}catch(e){if(ticket===this.tabTicket)this.error=e.message;}},async supervise(){const row=this.selected,closed=row.state==='CLOSED';const result=await this.command('/stores/'+row.id+(closed?'/reopen':'/close'),closed?'恢复店铺':'关闭店铺',{expectedVersion:row.version},row.storeName+'。'+(closed?'恢复不会补齐失效证照或自动上架商品。':'立即失效新增经营资格，合法人员保留受限整改和历史查询。'));if(result)await this.reload();},async revoke(q){const result=await this.command('/qualifications/'+q.id+'/revoke','撤销当前资质',{expectedVersion:q.version},this.selected.storeName+' · '+this.status(q.type)+' v'+q.revision+'；仅相应范围重算资格。');if(result)await this.reload();}}};</script>
